script:
if doc.workflow_state == "Approved":

    if not doc.custom_approved_by_signature:

        user = frappe.session.user

        signature = frappe.db.get_value(
            "Approval Signature Settings",
            {
                "approver_user": user
            },
            "signature"
        )

        if signature:
            doc.custom_approved_by_signature = signature
